#!/usr/bin/env node
/**
 * Build (or update) the Zimmermann content model as a single, organization-scoped
 * Contentful Environment Template — the mechanism Contentful now expects content
 * models to be authored through, replacing the old per-environment sync.js +
 * migrations/*.mjs pipeline (see scripts/contentful/README.md).
 *
 * Every file in ./content-types/ defines one content type; this script assembles all
 * of them into one EnvironmentTemplate's `entities.contentTypeTemplates`, get-or-creates
 * it by name under CONTENTFUL_ORGANIZATION_ID, and bumps its version. The template
 * itself does not touch any space or environment — see setup/installTemplate.mjs for
 * pushing it into one.
 *
 * Usage:
 *   npm run sync:contentful
 *   npm run sync:contentful -- --version-name "add region/link/footer/uiCopy models"
 */

'use strict';

const contentfulManagement = require('contentful-management');
const path = require('path');
const fs = require('fs');

/**
 * @typedef {Object} FieldDefinition
 * @property {string} id
 * @property {string} name
 * @property {string} type
 * @property {string} [linkType]
 * @property {boolean} [required]
 * @property {boolean} [localized]
 * @property {Record<string, unknown>} [defaultValue]
 * @property {string} [helpText]
 * @property {Array<Record<string, unknown>>} [validations]
 * @property {{type: string, linkType?: string, validations?: Array<Record<string, unknown>>}} [items]
 */

/**
 * @typedef {Object} ContentTypeDefinition
 * @property {string} id
 * @property {string} name
 * @property {string} [displayField]
 * @property {string} [description]
 * @property {FieldDefinition[]} fields
 */

const REQUIRED_ENV = ['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_ORGANIZATION_ID'];

// The one EnvironmentTemplate this repo owns. Looked up by name (get-or-create) rather
// than a stored ID, matching the get-or-create idiom the rest of this pipeline already
// uses — no ID to keep in sync across machines/CI.
const TEMPLATE_NAME = 'Zimmermann Content Model';

function checkEnv() {
  const missing = REQUIRED_ENV.filter((k) => !process.env[k]);
  if (missing.length) {
    console.error(`\n❌  Missing env vars: ${missing.join(', ')}`);
    console.error('   Add them to .env (at repo root) and re-run.\n');
    process.exit(1);
  }
}

function getArg(flag) {
  const args = process.argv.slice(2);
  const i = args.indexOf(flag);
  return i !== -1 ? args[i + 1] : null;
}

/**
 * Build a Content Type Template field payload. Same shape as a plain content-type
 * field, `localized` just needs to be explicit now — there is no longer a migration
 * file layered on top to override an inferior default.
 * @param {FieldDefinition} def
 */
function buildField(def) {
  /** @type {Record<string, unknown>} */
  const field = {
    id: def.id,
    name: def.name,
    type: def.type,
    required: def.required ?? false,
    localized: def.localized ?? false,
    validations: def.validations ?? [],
  };
  if (def.linkType) field.linkType = def.linkType;
  if (def.items) field.items = def.items;
  if (def.defaultValue) field.defaultValue = def.defaultValue;
  return field;
}

/** @param {ContentTypeDefinition} def */
function buildContentTypeTemplate(def) {
  return {
    id: def.id,
    name: def.name,
    displayField: def.displayField,
    description: def.description ?? '',
    fields: def.fields.map(buildField),
  };
}

async function main() {
  checkEnv();

  const organizationId = process.env.CONTENTFUL_ORGANIZATION_ID;
  const versionName = getArg('--version-name') ?? new Date().toISOString();
  const versionDescription = getArg('--version-description') ?? undefined;

  const client = contentfulManagement.createClient(
    { accessToken: process.env.CONTENTFUL_MANAGEMENT_TOKEN },
    { type: 'plain' },
  );

  const defsDir = path.join(__dirname, 'content-types');
  const files = fs
    .readdirSync(defsDir)
    .filter((f) => f.endsWith('.js'))
    .sort();

  if (!files.length) {
    console.log('No content type definitions found in scripts/contentful/content-types/');
    return;
  }

  const contentTypeTemplates = files.map((file) => {
    const def = /** @type {ContentTypeDefinition} */ (require(path.join(defsDir, file)));
    console.log(`→ Including "${def.id}" (${file})`);
    return buildContentTypeTemplate(def);
  });

  const { items: existing } = await client.environmentTemplate.getMany({
    organizationId,
    query: { limit: 100 },
  });
  const found = existing.find((t) => t.name === TEMPLATE_NAME);

  if (!found) {
    await client.environmentTemplate.create(
      { organizationId },
      {
        name: TEMPLATE_NAME,
        description: 'Zimmermann PWA content model — every content type in one place, installed per environment.',
        versionName,
        versionDescription,
        entities: { contentTypeTemplates, editorInterfaceTemplates: [] },
      },
    );
    console.log(`  ✅  Created EnvironmentTemplate "${TEMPLATE_NAME}"`);
    console.log('\n✅  Build complete.\n');
    return;
  }

  found.entities = { contentTypeTemplates, editorInterfaceTemplates: found.entities.editorInterfaceTemplates ?? [] };
  found.versionName = versionName;
  found.versionDescription = versionDescription;

  await client.environmentTemplate.update({ organizationId, environmentTemplateId: found.sys.id }, found);
  console.log(`  ♻️   Updated EnvironmentTemplate "${TEMPLATE_NAME}"`);
  console.log('\n✅  Build complete. Run `npm run install:contentful -- --target <env>` to push this out.\n');
}

main().catch((err) => {
  console.error('\n❌  Build failed:', err.message ?? err);
  process.exit(1);
});

