#!/usr/bin/env node
/**
 * Bootstrap the Zimmermann Contentful space.
 *
 * Creates environments, locales, per-environment API keys, and the production
 * alias for the six-tier delivery pipeline. Idempotent — safe to re-run.
 *
 * Tier topology:
 *   DEV (dev) → TEST (test) → OMS INT (sit) → STAGE (staging) → UAT (uat) → PROD (master / production alias)
 *
 * Usage:
 *   npm run setup:contentful
 *   npm run setup:contentful -- --dry-run
 *
 * Required env vars (via .env):
 *   CONTENTFUL_MANAGEMENT_TOKEN, CONTENTFUL_SPACE_ID
 */

import {
  checkEnv,
  createClient,
  pollForReady,
  getExistingEnvironmentIds,
  getExistingLocaleCodes,
  log,
} from './_shared.mjs';

const DRY_RUN = process.argv.includes('--dry-run');

if (DRY_RUN) console.log('\n🔍  DRY RUN — no changes will be made.\n');

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);

// Environments to create, cloned from master.
// master is created automatically by Contentful.
const TARGET_ENVIRONMENTS = ['dev', 'test', 'sit', 'staging', 'uat'];

// Locales — codes match SFCC sites.js locale IDs exactly so no mapping is needed.
// en (AU) is the default/fallback; all others fall back to en.
const LOCALES = [
  { code: 'en',    name: 'English (AU)',             default: true,  fallbackCode: null  },
  { code: 'en-US', name: 'English (US)',              default: false, fallbackCode: 'en' },
  { code: 'en-GB', name: 'English (UK / EU)',         default: false, fallbackCode: 'en' },
  { code: 'fr',    name: 'French (EU)',               default: false, fallbackCode: 'en' },
  { code: 'it',    name: 'Italian (EU)',              default: false, fallbackCode: 'en' },
  { code: 'es',    name: 'Spanish (EU)',              default: false, fallbackCode: 'en' },
  { code: 'en-CH', name: 'English (EU International)', default: false, fallbackCode: 'en' },
  { code: 'en-HK', name: 'English (HK)',              default: false, fallbackCode: 'en' },
  { code: 'en-AE', name: 'English (ME)',              default: false, fallbackCode: 'en' },
];

// Aliases to create/maintain.
// production alias is what the MRT production tier points to — flipping it
// is the zero-downtime release mechanism. master is kept in sync with it.
const ALIASES = ['production'];

const results = {
  environments: { created: [], skipped: [] },
  locales: { created: [], skipped: [], failed: [] },
  apiKeys: { created: [], skipped: [] },
  aliases: { created: [], updated: [], skipped: [] },
};

async function main() {
  const client = createClient();

  // ── 1. Environments ─────────────────────────────────────────────────────────
  log.section('Environments');

  const { items: envItems } = await client.environment.getMany({ query: { limit: 100 } });
  const existingById   = new Map(envItems.map((e) => [e.sys.id, e]));
  const existingByName = new Map(envItems.map((e) => [e.name,   e]));
  log.info(`Existing: ${[...existingById.keys()].join(', ')}`);

  for (const envId of TARGET_ENVIRONMENTS) {
    if (existingById.has(envId)) {
      log.skip(`Environment '${envId}' already exists`);
      results.environments.skipped.push(envId);
      continue;
    }
    // An environment with this name exists but was created with a wrong auto-generated ID
    // (can happen if a previous run failed mid-way using create() instead of createWithId())
    if (existingByName.has(envId)) {
      const orphan = existingByName.get(envId);
      log.warn(`Environment named '${envId}' exists with ID '${orphan.sys.id}'. Delete it in the Contentful web UI then re-run.`);
      results.environments.skipped.push(envId);
      continue;
    }
    if (DRY_RUN) {
      log.info(`[dry-run] Would create environment '${envId}' (clone of master)`);
      results.environments.created.push(envId);
      continue;
    }
    log.info(`Creating environment '${envId}' (cloning from master)...`);
    // createWithId ensures the environment's API ID matches its name (e.g. 'dev' → ID 'dev')
    await client.environment.createWithId({ environmentId: envId }, { name: envId }, 'master');
    process.stdout.write('  Waiting for ready');
    await pollForReady(client, envId);
    console.log();
    log.success(`Environment '${envId}' ready`);
    results.environments.created.push(envId);
  }

  // ── 2. Locales (set up in master; cloned environments inherit them) ─────────
  log.section('Locales');

  const existingLocales = await getExistingLocaleCodes(client, 'master');
  log.info(`Existing locales in master: ${existingLocales.join(', ')}`);

  for (const locale of LOCALES) {
    if (existingLocales.includes(locale.code)) {
      log.skip(`Locale '${locale.code}' already exists`);
      results.locales.skipped.push(locale.code);
      continue;
    }
    if (DRY_RUN) {
      log.info(`[dry-run] Would create locale '${locale.code}' (${locale.name})`);
      results.locales.created.push(locale.code);
      continue;
    }
    const payload = {
      name: locale.name,
      code: locale.code,
      default: locale.default,
      // Non-default locales are optional: required-localized fields can publish with
      // only 'en' set — translation is a separate, later pass through the translation
      // app, not a precondition for publishing English content. fallbackCode above
      // covers reads in the meantime.
      optional: !locale.default,
    };
    if (locale.fallbackCode) payload.fallbackCode = locale.fallbackCode;

    try {
      await client.locale.create({ environmentId: 'master' }, payload);
      log.success(`Created locale '${locale.code}' (${locale.name})`);
      results.locales.created.push(locale.code);
    } catch (err) {
      log.warn(`Failed to create locale '${locale.code}': ${err.message ?? err}. Skipping — re-run later to retry.`);
      results.locales.failed.push(locale.code);
    }
  }

  // ── 3. Per-environment API keys (Delivery + Preview) ────────────────────────
  log.section('API Keys');

  const { items: existingKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
  const existingKeyNames = new Set(existingKeys.map((k) => k.name));

  const allEnvs = ['master', ...TARGET_ENVIRONMENTS];
  for (const envId of allEnvs) {
    const tierLabel = envId === 'master' ? 'PRODUCTION' : envId.toUpperCase();
    const keyName = `Zimmermann ${tierLabel} — Delivery`;

    if (existingKeyNames.has(keyName)) {
      log.skip(`API key '${keyName}' already exists`);
      results.apiKeys.skipped.push(envId);
      continue;
    }
    if (DRY_RUN) {
      log.info(`[dry-run] Would create API key '${keyName}'`);
      results.apiKeys.created.push(envId);
      continue;
    }
    await client.apiKey.create(
      {},
      {
        name: keyName,
        environments: [{ sys: { type: 'Link', linkType: 'Environment', id: envId } }],
      },
    );
    log.success(`Created API key '${keyName}'`);
    results.apiKeys.created.push(envId);
  }

  // ── 4. Aliases ───────────────────────────────────────────────────────────────
  log.section('Aliases');

  const { items: existingAliases } = await client.environmentAlias.getMany({});
  const existingAliasMap = Object.fromEntries(
    existingAliases.map((a) => [a.sys.id, a.environment.sys.id]),
  );

  for (const aliasId of ALIASES) {
    const currentTarget = existingAliasMap[aliasId];
    if (currentTarget === 'master') {
      log.skip(`Alias '${aliasId}' already points to master`);
      results.aliases.skipped.push(aliasId);
      continue;
    }
    if (DRY_RUN) {
      const action = currentTarget ? `update (currently → ${currentTarget})` : 'create';
      log.info(`[dry-run] Would ${action} alias '${aliasId}' → master`);
      (currentTarget ? results.aliases.updated : results.aliases.created).push(aliasId);
      continue;
    }
    // The plain client has no createOrUpdate for environmentAlias — an existing alias
    // must go through update() (which needs its current sys.version), a new one through
    // createWithId().
    const targetLink = { environment: { sys: { type: 'Link', linkType: 'Environment', id: 'master' } } };
    if (currentTarget) {
      const existing = await client.environmentAlias.get({ environmentAliasId: aliasId });
      await client.environmentAlias.update({ environmentAliasId: aliasId }, { ...existing, ...targetLink });
    } else {
      await client.environmentAlias.createWithId({ environmentAliasId: aliasId }, targetLink);
    }
    const action = currentTarget ? 'Updated' : 'Created';
    log.success(`${action} alias '${aliasId}' → master`);
    (currentTarget ? results.aliases.updated : results.aliases.created).push(aliasId);
  }

  // ── Summary ──────────────────────────────────────────────────────────────────
  console.log('\n╔══════════════════════════════════════╗');
  console.log('║  Bootstrap Summary                   ║');
  console.log('╚══════════════════════════════════════╝');
  console.log(`  Environments  created: [${results.environments.created.join(', ')}]  skipped: [${results.environments.skipped.join(', ')}]`);
  console.log(`  Locales       created: [${results.locales.created.join(', ')}]  skipped: [${results.locales.skipped.join(', ')}]  failed: [${results.locales.failed.join(', ')}]`);
  console.log(`  API keys      created: [${results.apiKeys.created.join(', ')}]  skipped: [${results.apiKeys.skipped.join(', ')}]`);
  console.log(`  Aliases       created: [${results.aliases.created.join(', ')}]  updated: [${results.aliases.updated.join(', ')}]  skipped: [${results.aliases.skipped.join(', ')}]`);

  if (!DRY_RUN && results.apiKeys.created.length > 0) {
    console.log('\n  ℹ️   Run  npm run config:contentful  to populate .env with the new API tokens.\n');
  }
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

