  console.log(`  API keys      created: [${results.apiKeys.created.join(', ')}]  skipped: [${results.apiKeys.skipped.join(', ')}]`);
  console.log(`  Aliases       created: [${results.aliases.created.join(', ')}]  updated: [${results.aliases.updated.join(', ')}]  skipped: [${results.aliases.skipped.join(', ')}]`);

  if (!DRY_RUN && results.apiKeys.created.length > 0) {
    console.log('\n  ℹ️   Run  npm run config:contentful  to populate .env with the new API tokens.\n');
  }
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

